import sys
from openpyxl import load_workbook

PATH = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
wb = load_workbook(PATH, data_only=True)
print("Sheets:", wb.sheetnames)
grand = 0.0
for ws in wb.worksheets:
    print(f"\n=== Sheet: {ws.title} (max_row={ws.max_row}, max_col={ws.max_column}) ===")
    rows = list(ws.iter_rows(values_only=True))
    for r, row in enumerate(rows, 1):
        for c, v in enumerate(row, 1):
            if v is not None:
                print(f"{ws.cell(row=r, column=c).coordinate}: {v!r}")
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                grand += v
    if rows:
        print("Header row:", rows[0])
        for c, h in enumerate(rows[0], 1):
            col_sum = 0.0
            has_num = False
            for row in rows[1:]:
                if c <= len(row):
                    v = row[c - 1]
                    if isinstance(v, (int, float)) and not isinstance(v, bool):
                        col_sum += v
                        has_num = True
            if has_num:
                print(f"Column {c} header={h!r} numeric_sum={col_sum}")
print(f"\nGRAND TOTAL (all numeric cells): {grand}")

